    val reason: String,
    /** How long until play resumed; absent if it never did (an abandonment follows). */
    val lengthSec: Long? = null,
    val note: String? = null,
) : Event

/** The referee corrected a clock during play (TMR-14); periodSec is the period's time just after. Events before it keep their times, and the added-time stats leave a period with its match clock corrected out (STAT-9). */
@Serializable
data class EventClockAdjusted(
    override val type: String = "clockAdjusted",
    val `when`: String,
    /** 1-based; extra-time periods follow the normal ones. */
