/** A Event of a kind this app doesn't know yet (from a newer server). */
@Serializable
data class EventUnknown(override val type: String = "") : Event

object EventSerializer : JsonContentPolymorphicSerializer<Event>(Event::class) {
    override fun selectDeserializer(element: JsonElement): DeserializationStrategy<Event> =
        when ((element as? JsonObject)?.get("type")?.let { (it as? JsonPrimitive)?.content }) {
            "goal" -> EventGoal.serializer()
            "caution" -> EventCaution.serializer()
            "secondCaution" -> EventSecondCaution.serializer()
            "sendOff" -> EventSendOff.serializer()
            "sinBin" -> EventSinBin.serializer()
            "secondSinBin" -> EventSecondSinBin.serializer()
            "stoppage" -> EventStoppage.serializer()
            "periodEnd" -> EventPeriodEnd.serializer()
            "penaltyKick" -> EventPenaltyKick.serializer()
            "injury" -> EventInjury.serializer()
            "suspension" -> EventSuspension.serializer()
            "clockAdjusted" -> EventClockAdjusted.serializer()
            "abandonment" -> EventAbandonment.serializer()
            else -> EventUnknown.serializer()
        }
}

