    /** Ask the goal type (goal, DFK, penalty, own goal) for each goal (EVT-8). */
    val goalTypes: Boolean,
    val extraTime: Boolean,
    val extraTimePeriods: Int,
    val extraTimePeriodSec: Int,
    /** With extra time, a goal in it ends the match, the scoring team winning (ET-6). Missing means off. */
    val goldenGoal: Boolean? = null,
    val penalties: Boolean,
    /** Temporary dismissals (EVT-12): Sin bin in the watch's team menu, a countdown with the match clock. Missing means off. */
