@Serializable(with = OffenderSerializer::class)
sealed interface Offender {
    val kind: String
}

@Serializable
data class OffenderPlayer(
    override val kind: String = "player",
    val number: Int? = null,
) : Offender

@Serializable
data class OffenderTeamOfficial(
    override val kind: String = "teamOfficial",
    val role: String,
    val name: String? = null,
) : Offender

/** A Offender of a kind this app doesn't know yet (from a newer server). */
@Serializable
data class OffenderUnknown(override val kind: String = "") : Offender

object OffenderSerializer : JsonContentPolymorphicSerializer<Offender>(Offender::class) {
    override fun selectDeserializer(element: JsonElement): DeserializationStrategy<Offender> =
        when ((element as? JsonObject)?.get("kind")?.let { (it as? JsonPrimitive)?.content }) {
            "player" -> OffenderPlayer.serializer()
            "teamOfficial" -> OffenderTeamOfficial.serializer()
            else -> OffenderUnknown.serializer()
        }
}

