    /** Phone notifications a day (from midnight UTC), across all the account's phones (PLAN-8). Left out: no limit; 0: none at all. */
    val pushPerDay: Int? = null,
    /** API keys (KEY-1). Left out: no limit; 0: none at all. */
    val apiKeys: Int? = null,
    /** Requests made with the account's API keys a minute, all its keys together (PLAN-8). Left out: no limit; 0: none at all. */
    val apiCallsPerMinute: Int? = null,
    /** Requests made with the account's API keys a day (from midnight UTC), all its keys together (PLAN-8). Left out: no limit; 0: none at all. */
    val apiCallsPerDay: Int? = null,
    /** Webhooks (HOOK-1). Left out: no limit; 0: none at all. */
    val webhooks: Int? = null,
    /** Assignor calendars (FEED-10). Left out: no limit; 0: none at all. */
