/** What this server is and offers, so apps can adapt to older or self-hosted servers. */
@Serializable
data class ServerMeta(
    val product: String,
    /** The address apps should use for the API, which may differ from the one they came through (APP-13). */
    val apiUrl: String? = null,
    /** Raised when the API changes in a way older apps can't follow. */
    val apiVersion: Long,
    /** Where this server describes its own API as OpenAPI (AGT-3); missing on servers from before it. */
    val openApiUrl: String? = null,
    /** The server's version (VER-1): the day of its last change, "2026.10.30" ("2026.10.30.2" for a second change that day), or "dev" when run from a checkout without git. Missing on servers from before it. */
    val version: String? = null,
    /** The commit it was built from, "f5de635". */
    val commit: String? = null,
    /** What this server offers: accounts, records, changes, tracks and stats (missing on servers from before them), devices, link, watch, people, invites, calendar and import, then email, geocode, push, notices (with push, from servers that tell phones what integrations did, NOTE-1) and weather when they're switched on; merging, from servers that find duplicates and preview merges for the apps (DUP-11); plans, from servers with plans and the account's time zone (PLAN-6, PLAN-9); assignor-calendars, from servers that read assignors' calendar links (FEED-1). Ignore names you don't know. */
    val capabilities: List<String>,
    val maps: ServerMetaMaps,
    /** The address search service behind GET /v1/geocode, to credit it. */
    val geocoder: ServerMetaGeocoder? = null,
    /** Whose weather data GET /v1/weather uses, to credit it. */
    val weather: ServerMetaWeather? = null,
    /** Nobody has an account on this server yet (USR-8): the first one can be made whatever signUp says, with the setup code when setupCodeNeeded, and it's the server's admin. */
    val firstAccount: Boolean? = null,
    /** The first account needs the code in the server's logs (ADM-5). */
    val setupCodeNeeded: Boolean? = null,
    /** The first account hasn't finished setting the server up (ADM-5). */
    val setupPending: Boolean? = null,
    /** The server's own address (PUBLIC_URL), for the website to say if it isn't HTTPS (ADM-5, ADM-6). */
    val publicUrl: String? = null,
    /** Who can make an account (USR-2); missing on servers from before it, which were open or closed. */
    val signUp: String? = null,
)

/** Settings for the whole server that admins change in the web app (ADM-1, ADM-2), sending only those that change. One the environment sets is fixed there and can't be changed. */
@Serializable
data class ServerSettings(
    /** Who can make an account (USR-2, SIGN_UP). */
    val signUp: String? = null,
    /** Email through an SMTP server: smtp://user:password@host:587 or smtps://…:465. A secret: never sent back (SMTP_URL). null or "" clears it, back to the default. */
    val smtpUrl: String? = null,
    /** The sender, "LawFive <lawfive@example.com>" (MAIL_FROM). null or "" clears it, back to the default. */
    val mailFrom: String? = null,
    /** A MapLibre style for the map, or off for raster tiles (MAP_STYLE_URL). null or "" clears it, back to the default. */
    val mapStyleUrl: String? = null,
    /** The style for dark mode (MAP_STYLE_DARK_URL). null or "" clears it, back to the default. */
    val mapStyleDarkUrl: String? = null,
    /** The style's credit, as HTML (MAP_STYLE_ATTRIBUTION). null or "" clears it, back to the default. */
    val mapStyleAttribution: String? = null,
    /** Raster tiles, with {z}, {x} and {y} (MAP_TILE_URL). null or "" clears it, back to the default. */
    val mapTileUrl: String? = null,
    /** The tiles' credit, as HTML (MAP_ATTRIBUTION). null or "" clears it, back to the default. */
    val mapAttribution: String? = null,
    /** Satellite tiles, with the provider's key (MAP_SATELLITE_URL). null or "" clears it, back to the default. */
    val mapSatelliteUrl: String? = null,
    /** Their credit, as HTML (MAP_SATELLITE_ATTRIBUTION). null or "" clears it, back to the default. */
    val mapSatelliteAttribution: String? = null,
    /** Address search (Nominatim-compatible), or off (GEOCODER_URL). null or "" clears it, back to the default. */
    val geocoderUrl: String? = null,
    /** Forecasts (Open-Meteo-compatible), or off (WEATHER_URL). null or "" clears it, back to the default. */
    val weatherUrl: String? = null,
    /** Past weather for played matches, or off (WEATHER_HISTORY_URL). null or "" clears it, back to the default. */
    val weatherHistoryUrl: String? = null,
    /** For a paid plan. A secret: never sent back (WEATHER_API_KEY). null or "" clears it, back to the default. */
    val weatherApiKey: String? = null,
    /** Weather calls a day at most (WEATHER_DAILY_LIMIT). null or "" clears it, back to the default. */
    val weatherDailyLimit: String? = null,
    /** true lets webhooks reach private and local addresses (WEBHOOK_ALLOW_PRIVATE). null or "" clears it, back to the default. */
    val webhookAllowPrivate: String? = null,
)

